(() => {
  'use strict';
  const B=window.LessonBook,C=window.ACTIVE_COURSE,E=B.escape,app=document.getElementById('app'),isReview=C.type==='review',WORD=(C.word||C.writeWord).toUpperCase(),COUNT=B.total(C),shortPractice=C.type==='word'&&C.date>='2026-10-15';
  const steps=isReview?[...C.questions.map((_,i)=>({name:'小挑战 '+(i+1),title:C.questions[i].prompt})),{name:'动手用一用',title:'离开屏幕，把英语用起来。'}]:[{name:'听一听',title:`${C.meaning}的英语，叫 ${C.word}。`},{name:'词义配图',title:`听声音，找到${C.meaning}。`},{name:'说一说',title:'轮到你的声音啦。'},{name:'用一用',title:'把新朋友放进一句话。'},{name:'拼一拼',title:`用字母搭出 ${C.word}。`},{name:'写一写',title:'留下你的笔迹。'}];
  const fresh=()=>({screen:'home',stage:0,completed:[],wordSeen:false,listenRound:0,awaiting:false,said:false,phrases:[false,false],sentence:0,letters:[],usedLetters:[],strokes:[],showGuide:true,paper:false,writingDone:false,finishedAt:null,...B.preferences()});
  const bank=[...WORD,'A','N'].map((letter,index)=>({letter,key:index})).sort((a,b)=>(a.key*7%11)-(b.key*7%11));
  function read(){const raw=B.read(B.storageKey(C));if(!raw||!['home','lesson','complete'].includes(raw.screen)||!Number.isInteger(raw.stage)||raw.stage<0||raw.stage>=COUNT)return fresh();const s={...fresh(),...raw,...B.preferences()};s.completed=Array.isArray(s.completed)?[...new Set(s.completed.filter(i=>Number.isInteger(i)&&i>=0&&i<COUNT))]:[];s.strokes=Array.isArray(s.strokes)?s.strokes.slice(0,200).filter(st=>Array.isArray(st)&&st.every(p=>p&&Number.isFinite(p.x)&&Number.isFinite(p.y))).map(st=>st.slice(0,1500)):[];s.phrases=Array.isArray(s.phrases)&&s.phrases.length===2?s.phrases.map(Boolean):[false,false];s.sentence=s.sentence===1?1:0;s.listenRound=Math.min(3,Math.max(0,Number(s.listenRound)||0));s.letters=Array.isArray(s.letters)&&WORD.startsWith(s.letters.join(''))&&s.letters.length<=WORD.length?s.letters:[];s.usedLetters=Array.isArray(s.usedLetters)?s.usedLetters.filter(i=>Number.isInteger(i)&&i>=0&&i<bank.length):[];if(s.screen==='complete'&&s.completed.length!==COUNT)s.screen='lesson';return s;}
  let listenReady=false,choiceAttempt=0,practiceHeard=false;
  let state=read(),hint=false,observer=null,toastTimer;
  function save(){B.progressSaveFailed=!B.write(B.storageKey(C),state);B.savePreferences(state);B.renderGrowth(window.COURSE_LIBRARY);}
  const toast=text=>{const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000);};
  const voice=window.createLessonVoice({settings:()=>state,save,toast}),en=text=>({text,lang:'en-US'}),zh=text=>({text,lang:'zh-CN'}),speak=(text,slow=false,force=false,complete)=>voice.say(text,slow,force,complete);
  const audio=(label='听一听',action='listen')=>`<button class="speak-button" data-action="${action}"><span aria-hidden="true">◖))</span> ${label}</button>`;
  const feedback=text=>`<div class="feedback" role="status" aria-live="polite">${text}</div>`;
  const done=i=>state.completed.includes(i);
  function earn(i){if(!done(i)){state.completed.push(i);toast('获得一颗探险星 ★');}save();}
  function ready(){if(isReview)return done(state.stage);return [state.wordSeen,state.listenRound===3,state.said,state.phrases.every(Boolean),state.letters.length===WORD.length,state.writingDone][state.stage];}
  const bottom=note=>`<div class="lesson-bottom"><p>${note}</p><button class="button primary" data-action="next" ${ready()?'':'disabled'}>${state.stage===COUNT-1?'领取探险徽章':'下一关'} →</button></div>`;
  function hearChoice(force=true){listenReady=false;render();speak(C.word,false,force,()=>{if(state.screen!=='lesson'||state.stage!==1)return;listenReady=true;render();});}
  function hearWord(slow=false,force=true){const stage=state.stage;speak(C.word,slow,force,()=>{if(state.screen!=='lesson'||state.stage!==stage)return;if(stage===0){state.wordSeen=true;earn(0);render();}});}
  function practicePhase(){return state.said?'done':['model','echo','recall','compare'].includes(state.practicePhase)?state.practicePhase:'model';}
  function hearPractice(force=true){const phase=practicePhase();practiceHeard=false;render();speak(C.word,false,force,()=>{if(state.screen!=='lesson'||state.stage!==2||practicePhase()!==phase)return;practiceHeard=true;if(phase==='recall'){state.practicePhase='compare';save();}render();});}
  function practice(){const phase=practicePhase(),completedPractice=state.practicePhase==='done',hidden=phase==='recall'&&!state.practiceHelp;return `<div class="say-card">${B.art(C.art)}${hidden?'<span class="big-word">?</span><p>先不看单词，自己想一想、说一次。</p>':`<span class="big-word" lang="en">${E(C.word)}</span>`}<span class="stage-tag">${{model:'① 自然听，跟着说',echo:'② 做一次小回声',recall:'③ 自己回忆，再听核对',compare:'听过示范，再比较一下',done:'短练习完成'}[phase]}</span><p>${{model:'示范播完会停下来。轮到你慢慢跟着说，不用赶时间。',echo:'再听一次自然读音，像小回声一样试着说一次。',recall:'想不起来可以求助。先自己试着说，再听示范。',compare:'和刚才自己说的比一比。不同也没关系，可以再试一次。',done:completedPractice?'你参与了听、跟读和回忆。这不是自动发音评分。':'已保留以前的跟读完成记录；不代表完成了新增回忆练习，也不是发音评分。'}[phase]}</p><div>${phase==='recall'?'<button class="speak-button" data-action="practice-check">我先试着说了，听示范核对</button><button class="button secondary small" data-action="practice-help">给我提示</button>':audio('重听自然示范','practice-listen')}</div></div>${phase!=='recall'&&phase!=='done'?`<div class="parent-check"><span>${practiceHeard||phase==='compare'?'留出时间让孩子开口，再由家长确认。':'先完整听一次示范。'}<br>不录音、不计时、不判断发音对错。</span><button class="button secondary small" data-action="practice-confirm" ${practiceHeard||phase==='compare'?'':'disabled'}>${phase==='compare'?'家长确认：试说并核对过了':'家长确认：跟着试说过了'}</button></div>`:''}${phase==='done'?feedback(!completedPractice?'✓ 已保留原跟读完成记录。':state.practiceHelp?'✓ 用过提示，也完成了练习。之后可以再回忆一次。':'✓ 听过、试说过、回忆过啦！'):''}${bottom('短练习只记录参与；想多试可以重听，不规定五遍。')}`;}
  function stageSpeech(){if(isReview){if(state.stage<C.questions.length)speak([zh(C.questions[state.stage].prompt),en(C.questions[state.stage].speak)]);else speak(zh('和妈妈做完小任务，再写一次单词。'));return;}switch(state.stage){case 0:hearWord(false,false);break;case 1:hearChoice(false);break;case 2:if(shortPractice){if(!['recall','done'].includes(practicePhase()))hearPractice(false);}else speak([zh('听一次，再跟着说'),en(C.word)]);break;case 3:speak([zh('和妈妈一起说这句话'),en(C.phrases[state.sentence].text)]);break;case 4:speak([zh('用字母拼出'),en(C.word)]);break;case 5:speak([zh('用手指或者纸笔，写下'),en(C.word)]);break;}}
  function home(){const p=state.completed.length;return `<section class="hero course-hero"><div class="hero-copy"><span class="eyebrow">${C.date.replaceAll('-','.')} · ${E(C.theme)}</span><h1>${E(C.title)}<span class="hero-en" lang="en">${isReview?'Let’s play!':'Hello, '+E(C.word)+'!'}</span></h1><p>${isReview?'今天不学新词，把认识的朋友用起来。':E(C.context)}<br>和妈妈一起，慢慢听、慢慢试。</p><div class="hero-meta"><span>${C.minutes} 分钟</span><i class="meta-dot"></i><span>${COUNT} 个小任务</span></div><button class="button primary" data-action="start">${p===COUNT?'再探险一次':p?'继续探险':'开始探险'} ↗</button>${p?'<button class="resume-link" data-action="ask-restart">想从头学？重新开始</button>':''}<div class="hero-note">${isReview?'记不住也没关系，可以回书架再听一遍。':'先听、再说，最后动手写一次。'}</div></div><div class="hero-art course-art">${isReview?'<span class="review-medal" aria-hidden="true">★</span>':B.art(C.art)}</div></section><div class="path-heading"><h3>今天的探险路线</h3><span>一颗一颗，收集探险星</span></div><div class="journey">${steps.map((s,i)=>`<div class="journey-card"><span class="journey-icon">${done(i)?'★':i+1}</span><div><b>${s.name}</b><small>${done(i)?'已完成':'等你来试'}</small></div></div>`).join('')}</div>`;}
  function writing(){const hasInk=state.strokes.some(st=>st.length>1);return `<div class="writing-wrap"><div class="writing-bar"><span class="mini-word" lang="en">${E(C.word||C.writeWord)}</span><div class="writing-tools"><button data-action="guide" aria-pressed="${state.showGuide}">${state.showGuide?'隐藏描红':'显示描红'}</button><button data-action="clear-writing">清空重写</button></div></div><div class="canvas-wrap"><canvas id="writing-canvas" tabindex="0" aria-label="${E(C.word||C.writeWord)} 手写区域，可以用手指写"></canvas></div><p class="writing-help">用手指在上面写。笔迹会保存在这台设备上；这一版由妈妈确认，不会自动判定字母。</p><label class="paper-option"><input type="checkbox" data-action="paper" ${state.paper?'checked':''}>我在纸上写，不在屏幕上写</label><div class="writing-bottom"><p>大写、小写都可以。写一次就很棒。</p><button class="button secondary small" data-action="written" ${hasInk||state.paper||state.writingDone?'':'disabled'}>${state.writingDone?'✓ 写过啦':'妈妈确认：写过啦'}</button></div></div>`;}
  function wordStage(){switch(state.stage){case 0:return `<div class="stage-grid"><button class="cube-button" data-action="word" aria-label="听 ${E(C.word)} 的发音">${B.art(C.art)}</button><div class="word-panel"><span class="stage-tag">今天的单词</span><span class="big-word" lang="en">${C.word}</span><div class="pronunciation">${E(C.ipa)}</div><p class="word-meaning">${E(C.meaning)}</p>${audio('听发音','word')}${audio('慢一点','slow-word')}<p class="tiny-note">${E(C.context)}</p></div></div>${feedback(state.wordSeen?'✓ 认识新朋友啦！':'点图片或喇叭，先听一次。')}${bottom('妈妈可以指指图片，让孩子跟着听。')}`;
    case 1:{const order=[...C.choices];for(let n=0;n<Math.max(0,state.listenRound+choiceAttempt-(state.awaiting?1:0));n++)order.push(order.shift());return `<div class="listen-row">${audio('再听一次','word')}<span>找到 ${state.listenRound} / 3 次</span></div><div class="question-grid">${order.map(kind=>`<button class="object-option ${state.awaiting&&kind===C.word?'selected':''}" data-action="choose" data-kind="${kind}" aria-label="${B.names[kind]}" ${state.awaiting||!listenReady?'disabled':''}>${B.art(kind)}${state.awaiting&&kind===C.word?'<span class="answer-check">✓</span>':''}</button>`).join('')}</div>${feedback(state.listenRound===3?(state.choiceHelp?'✓ 在提示帮助下完成了，之后可以再试。':'★ 三次都找到了！'):state.awaiting?'✓ 找对了！':state.choiceHelp?'提示：找'+E(C.meaning)+'。换个位置，再听再试。':'听声音，然后选图片。')}${state.awaiting&&state.listenRound<3?'<button class="button orange small" data-action="next-round">再找一次 →</button>':''}${bottom('这里练习听词辨义、图片匹配，不是相近发音辨别。')}`;}
    case 2:if(shortPractice)return practice();return `<div class="say-card">${B.art(C.art)}<span class="big-word" lang="en">${C.word}</span><div>${audio('听示范','word')}${audio('慢速示范','slow-word')}</div></div><div class="parent-check"><span><b>给妈妈说一次：${C.word}！</b><br>不录音，由妈妈听一听。</span><button class="button secondary small" data-action="said">${state.said?'✓ 说出来了':'妈妈确认：说出来了'}</button></div>${feedback(state.said?'★ 你的声音，让单词活起来了！':'')}${bottom('听完留几秒，再让孩子试着开口。')}`;
    case 3:{const phrase=C.phrases[state.sentence];return `<div class="sentence-tab">${C.phrases.map((p,i)=>`<button data-action="sentence" data-index="${i}" class="${state.sentence===i?'active':''}">${state.phrases[i]?'✓ ':''}${E(p.action)}</button>`).join('')}</div><div class="scene-sentence"><div class="scene-illustration">${B.art(C.art)}</div><div><h3 lang="en">${E(phrase.text)}</h3><p>${E(phrase.translation)}</p>${audio('听这句话','phrase')}<p class="tiny-note">${E(phrase.action)}，试着和妈妈说。</p><button class="button secondary small" data-action="phrase-done">${state.phrases[state.sentence]?'✓ 这句说过啦':'我跟妈妈说完了'}</button></div></div>${feedback(state.phrases.every(Boolean)?'★ 两句都尝试说过啦！':'跟着说就可以，不要求背整句拼写。')}${bottom('妈妈可以先示范，再让孩子跟着做动作。')}`;}
    case 4:return `<div class="listen-row">${audio('听单词','word')}${audio('听字母顺序','letters')}</div><div class="spell-slots" aria-label="已拼出 ${state.letters.join('')}">${[...WORD].map((letter,i)=>`<div class="spell-slot ${i<state.letters.length?'filled':''}">${state.letters[i]||(hint&&i===state.letters.length?letter:'')}</div>`).join('')}</div><div class="letter-bank">${bank.map(({letter,key})=>`<button class="letter-tile ${state.usedLetters.includes(key)?'used':''}" data-action="letter" data-key="${key}" data-letter="${letter}" ${state.usedLetters.includes(key)||state.letters.length===WORD.length?'disabled':''}>${letter}</button>`).join('')}</div><div class="spell-tools"><button data-action="undo" ${state.letters.length?'':'disabled'}>↶ 撤回一个</button><button data-action="hint" ${state.letters.length===WORD.length?'disabled':''}>给我一个提示</button></div>${feedback(state.letters.length===WORD.length?'★ 你把单词搭出来啦！':'从第一个字母开始，遇到困难可以听提示。')}${bottom(E(C.phonics))}`;
    case 5:return writing()+feedback(state.writingDone?'★ 最后一颗星，属于你的认真尝试！':'')+bottom('手写不比较漂亮。请妈妈看一眼，再领取徽章。');}}
  function reviewStage(){if(state.stage===C.questions.length)return `<div class="practical-card"><span class="stage-tag">亲子小任务</span><h3>让英语走进生活。</h3><p>${E(C.practical)}</p>${audio('听任务')}</div>${writing()}${bottom('做完小任务、写完单词，再请妈妈确认。')}`;const q=C.questions[state.stage],solved=done(state.stage);return `<div class="listen-row">${audio('再听一次')}<span>挑战 ${state.stage+1} / ${C.questions.length}</span></div><div class="${q.kind==='picture'?'question-grid':'review-choices'}">${q.options.map((option,i)=>`<button class="${q.kind==='picture'?'object-option':'review-choice'} ${solved&&option===q.answer?'selected':''}" data-action="review-answer" data-index="${i}" aria-label="${E(q.kind==='picture'?B.names[option]:option)}" ${solved?'disabled':''}>${q.kind==='picture'?B.art(option):E(option)}${solved&&option===q.answer?'<span class="answer-check">✓</span>':''}</button>`).join('')}</div>${feedback(solved?'★ 做到了！':'选错也没关系，听一遍再试试。')}${bottom('如果记不住，可以回书架重玩对应的课程。')}`;}
  function finish(){const reviews=(!isReview&&C.date>='2026-10-15'?[]:C.reviewOf||[]).map(id=>window.COURSE_LIBRARY.lessons.find(c=>c.id===id)).filter(c=>c&&B.available(c));return `<section class="complete-panel"><div class="medal">★</div><span class="eyebrow">${C.date} · 探险完成</span><h1>${isReview?'这一周的小发现，你用起来啦！':'你好，'+E(C.meaning)+'小达人！'}</h1><p>听过、说过、动手试过，就是今天的收获。${state.choiceHelp?'这次找图用过提示，完成记录不代表已经掌握。':''}</p><div class="complete-stars">${'★'.repeat(COUNT)}</div>${!isReview?`<div class="certificate"><span class="big-word" lang="en">${C.word}</span><span class="word-meaning">${E(C.meaning)}</span></div><div class="review-card"><span>☀</span><div><b>离开屏幕，还有一个小任务</b><p>${E(C.realTask)}</p></div></div>`:''}<div class="button-row"><a class="button primary" href="index.html">回到课程书架</a><button class="button secondary" data-action="ask-restart">再探险一次</button></div>${reviews.length?`<div class="old-friends"><h3>再见见以前的朋友</h3><p>不看提示说一次，再点进课程检查。</p>${reviews.map(c=>`<a class="chip" href="${B.url(c)}">${E(c.word||'复习挑战')} ↗</a>`).join('')}</div>`:''}<p class="saved-note">本课进度和笔迹留在这台设备上。今天学完，就好好休息吧。</p></section>`;}
  function render(focus=false){observer?.disconnect();observer=null;if(shortPractice&&state.screen==='lesson'&&state.stage===2&&practicePhase()==='recall'&&!state.practiceHelp)document.getElementById('speech-status').textContent='';app.innerHTML=state.screen==='home'?home():state.screen==='complete'?finish():`<section class="lesson-shell"><div class="lesson-head"><button class="back-link" data-action="home">← 本课首页</button><nav class="progress-nav" aria-label="关卡进度">${steps.map((step,i)=>`<button class="step-dot ${state.stage===i?'active':done(i)?'done':''}" data-action="goto" data-stage="${i}" aria-label="第 ${i+1} 关：${step.name}" ${i>0&&!done(i-1)?'disabled':''}>${done(i)?'✓':i+1}</button>`).join('')}</nav><div class="star-count">★ ${state.completed.length} / ${COUNT}</div></div><div class="lesson-card"><div class="lesson-title"><span class="eyebrow">任务 ${state.stage+1} · ${steps[state.stage].name}</span><h2>${E(steps[state.stage].title)}</h2></div>${isReview?reviewStage():wordStage()}</div></section>`;const toggle=document.querySelector('.audio-toggle');toggle.setAttribute('aria-pressed',String(state.sound));toggle.setAttribute('aria-label',state.sound?'关闭语音':'开启语音');toggle.querySelector('.sound-label').textContent=state.sound?'语音开':'语音关';if(document.getElementById('writing-canvas'))initWriting();if(focus){app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'auto'});}}
  function initWriting(){const canvas=document.getElementById('writing-canvas'),ctx=canvas.getContext('2d');if(!ctx){toast('请用纸笔写，再让妈妈确认。');return;}let width=0,height=0,pointer=null,current;
    function paint(){ctx.clearRect(0,0,width,height);ctx.fillStyle='#faf9f1';ctx.fillRect(0,0,width,height);ctx.strokeStyle='#d8decd';ctx.lineWidth=1;ctx.setLineDash([7,6]);for(const y of [.3,.73]){ctx.beginPath();ctx.moveTo(18,height*y);ctx.lineTo(width-18,height*y);ctx.stroke();}ctx.setLineDash([]);if(state.showGuide){ctx.fillStyle='#dfe4d4';ctx.font=`800 ${Math.min(width/(WORD.length*.6),height*.6)}px ui-rounded,"Avenir Next",sans-serif`;ctx.textAlign='center';ctx.fillText((C.word||C.writeWord),width/2,height*.73);}ctx.strokeStyle='#315841';ctx.fillStyle='#315841';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';for(const stroke of state.strokes){if(!stroke.length)continue;if(stroke.length===1){ctx.beginPath();ctx.arc(stroke[0].x*width,stroke[0].y*height,2,0,Math.PI*2);ctx.fill();}else{ctx.beginPath();ctx.moveTo(stroke[0].x*width,stroke[0].y*height);for(const p of stroke.slice(1))ctx.lineTo(p.x*width,p.y*height);ctx.stroke();}}}
    const resize=()=>{const rect=canvas.getBoundingClientRect();width=rect.width;height=rect.height;const ratio=Math.min(window.devicePixelRatio||1,3);canvas.width=Math.round(width*ratio);canvas.height=Math.round(height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);paint();};
    const point=e=>{const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};};
    canvas.addEventListener('pointerdown',e=>{if(pointer!==null||state.strokes.length>=200||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();pointer=e.pointerId;current=[point(e)];state.strokes.push(current);canvas.setPointerCapture?.(pointer);paint();});
    canvas.addEventListener('pointermove',e=>{if(e.pointerId!==pointer||current.length>=1500)return;e.preventDefault();current.push(point(e));paint();});
    const up=e=>{if(e.pointerId!==pointer)return;pointer=null;save();const button=app.querySelector('[data-action="written"]');if(button)button.disabled=!(state.paper||state.writingDone||state.strokes.some(st=>st.length>1));};canvas.addEventListener('pointerup',up);canvas.addEventListener('pointercancel',up);canvas.addEventListener('lostpointercapture',up);resize();if('ResizeObserver' in window){observer=new ResizeObserver(resize);observer.observe(canvas);}}
  function go(i){if(i<0||i>=COUNT||(i>0&&!done(i-1)))return;voice.stop();state.screen='lesson';state.stage=i;listenReady=false;practiceHeard=false;hint=false;save();render(true);stageSpeech();}
  function message(text){const el=app.querySelector('.feedback');if(el)el.textContent=text;}
  document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action;switch(action){
    case 'home':voice.stop();state.screen='home';save();render(true);break;
    case 'start':go(state.completed.length===COUNT?0:state.stage);break;
    case 'goto':go(Number(target.dataset.stage));break;
    case 'next':if(!ready())break;if(state.stage<COUNT-1)go(state.stage+1);else{state.screen='complete';state.finishedAt=new Date().toISOString();save();render(true);speak(zh('探险完成，今天学得很认真！'));}break;
    case 'listen':stageSpeech();break;
    case 'word':case 'slow-word':if(!isReview&&state.stage===0)hearWord(action==='slow-word');else if(state.stage===1)hearChoice();else speak(C.word,action==='slow-word',true);break;
    case 'choose':if(state.awaiting||state.listenRound===3||!listenReady)break;if(target.dataset.kind===C.word){state.listenRound++;state.awaiting=true;if(state.listenRound===3)earn(1);save();render();speak([en(C.word),zh('找对了！')]);}else{choiceAttempt++;state.choiceHelp=true;listenReady=false;save();render();message('提示：找'+C.meaning+'。换个位置，再听一次试试。');hearChoice();}break;
    case 'next-round':if(!state.awaiting||state.listenRound>=3)break;state.awaiting=false;save();render();stageSpeech();break;
    case 'practice-listen':if(shortPractice&&state.stage===2)hearPractice();break;
    case 'practice-help':if(!shortPractice||state.stage!==2||practicePhase()!=='recall')break;state.practiceHelp=true;save();render();break;
    case 'practice-check':if(shortPractice&&state.stage===2&&practicePhase()==='recall')hearPractice();break;
    case 'practice-confirm':{if(!shortPractice||state.stage!==2)break;const phase=practicePhase();if(!practiceHeard&&phase!=='compare')break;voice.stop();practiceHeard=false;if(phase==='model')state.practicePhase='echo';else if(phase==='echo'){state.practicePhase='recall';document.getElementById('speech-status').textContent='';}else if(phase==='compare'){state.practicePhase='done';state.said=true;earn(2);}save();render();break;}
    case 'said':state.said=true;earn(2);render();speak(zh('你说出来啦！'));break;
    case 'sentence':state.sentence=Number(target.dataset.index)===1?1:0;save();render();speak(C.phrases[state.sentence].text);break;
    case 'phrase':speak(C.phrases[state.sentence].text);break;
    case 'phrase-done':state.phrases[state.sentence]=true;if(state.phrases.every(Boolean))earn(3);save();render();break;
    case 'letters':speak([...WORD].join('. ')+'.');break;
    case 'letter':{const letter=target.dataset.letter,key=Number(target.dataset.key);if(letter!==WORD[state.letters.length]){message('这块字母还不对，听提示再试一次。');break;}state.letters.push(letter);state.usedLetters.push(key);hint=false;if(state.letters.length===WORD.length)earn(4);save();render();speak(state.letters.length===WORD.length?C.word:letter);break;}
    case 'undo':state.letters.pop();state.usedLetters.pop();hint=false;save();render();break;
    case 'hint':hint=true;render();speak(WORD[state.letters.length]);break;
    case 'guide':state.showGuide=!state.showGuide;save();render();break;
    case 'clear-writing':state.strokes=[];save();render();break;
    case 'paper':state.paper=target.checked;save();render();break;
    case 'written':if(!state.paper&&!state.writingDone&&!state.strokes.some(st=>st.length>1))break;state.writingDone=true;earn(COUNT-1);render();speak(zh('认真写过啦，做得好！'));break;
    case 'review-answer':{if(!isReview||state.stage>=C.questions.length||done(state.stage))break;const q=C.questions[state.stage],option=q.options[Number(target.dataset.index)];if(option===q.answer){earn(state.stage);render();speak([en(q.speak),zh('找对了！')]);}else{message('再听一遍，再试试。');speak(q.speak);}break;}
    case 'sound':state.sound=!state.sound;save();voice.stop();render();break;
    case 'voices':document.getElementById('parent-dialog').close();voice.open();break;
    case 'close-voices':voice.close();break;
    case 'voice-demo-en':speak(isReview?[en(C.questions[0].speak)]:[en(C.word),...C.phrases.map(p=>en(p.text))],false,true);break;
    case 'voice-demo-zh':speak(zh('听一次，再跟着说'),false,true);break;
    case 'parent':document.getElementById('parent-dialog').showModal();break;
    case 'close-parent':document.getElementById('parent-dialog').close();break;
    case 'ask-restart':document.getElementById('restart-dialog').showModal();break;
    case 'cancel-restart':document.getElementById('restart-dialog').close();break;
    case 'restart':voice.stop();document.getElementById('restart-dialog').close();state=fresh();state.screen='lesson';practiceHeard=false;hint=false;save();render(true);stageSpeech();break;
  }});
  document.addEventListener('visibilitychange',()=>{if(document.hidden)voice.stop();});window.addEventListener('pagehide',()=>{voice.stop();save();});for(const id of ['parent-dialog','restart-dialog'])document.getElementById(id).addEventListener('cancel',()=>voice.stop());
  const parent=document.getElementById('parent-dialog');parent.querySelector('.dialog-lead').textContent=`今天是${isReview?'复习挑战':C.word+' · '+C.meaning}，约 ${C.minutes} 分钟。孩子想重玩也可以。`;parent.querySelector('.guide-list').innerHTML='<div><span>01</span><p><b>先听，再开口</b><br>点喇叭听示范，留几秒让孩子试着跟读。口语由你确认。</p></div><div><span>02</span><p><b>先认，再用起来</b><br>选错可以再试。指着图片，跟孩子做一个动作、说一句话。</p></div><div><span>03</span><p><b>动手写一次</b><br>用手指在画布写，或用纸笔。笔迹不自动判定，由你确认。</p></div>';
  render();
})();
